CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0');
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "users_is_admin_index" on "users" ("is_admin");
CREATE TABLE IF NOT EXISTS "articles" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "content" text not null, "featured_image" varchar, "image_brief" text, "seo_title" varchar, "meta_description" text, "target_city_slug" varchar, "target_district_slug" varchar, "faqs" text, "status" varchar not null default 'draft', "published_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "articles_slug_unique" on "articles" ("slug");
CREATE INDEX "articles_target_city_slug_index" on "articles" ("target_city_slug");
CREATE INDEX "articles_target_district_slug_index" on "articles" ("target_district_slug");
CREATE INDEX "articles_status_index" on "articles" ("status");
CREATE TABLE IF NOT EXISTS "cities" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "bps_code" varchar not null, "bps_province_code" varchar not null, "province" varchar not null, "island" varchar not null, "classification" varchar not null, "is_hub" tinyint(1) not null default '0', "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "cities_slug_unique" on "cities" ("slug");
CREATE UNIQUE INDEX "cities_bps_code_unique" on "cities" ("bps_code");
CREATE INDEX "cities_bps_province_code_index" on "cities" ("bps_province_code");
CREATE TABLE IF NOT EXISTS "kecamatans" ("id" integer primary key autoincrement not null, "city_id" integer not null, "name" varchar not null, "slug" varchar not null, "bps_code" varchar not null, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("city_id") references "cities"("id") on delete cascade);
CREATE UNIQUE INDEX "kecamatans_city_id_bps_code_unique" on "kecamatans" ("city_id", "bps_code");
CREATE INDEX "kecamatans_bps_code_index" on "kecamatans" ("bps_code");
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE IF NOT EXISTS "article_generation_jobs" ("id" varchar not null, "user_id" integer, "status" varchar not null default 'queued', "result" text, "error" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, primary key ("id"));
